(()=>{const g=__game; g.showScreen(null); g.mode='play'; g.player.release(); const out=[];
 for (const cp of g.course.checkpoints) { g.time=0; g.mode='play'; g.player.respawn(cp); let hit=null;
   g.simulate(12,(t,p)=>{ if(!hit&&(p.state==='hit'||p.state==='water')) hit=p.lastHit+'@'+t.toFixed(1)+'s'; return {}; });
   out.push('cp x='+cp.x.toFixed(1)+': '+(hit?'HIT '+hit:'safe 12s')); }
 return out})()
